/**
 * Continuous Improvement Loop - Automated optimization feedback.
 * ARCHITECTURE ONLY — declarations, no logic.
 */

import type { Timestamp, Json } from "../core/common";

/** Improvement proposal generated by the system. */
export interface ImprovementProposal {
  /** Unique proposal ID. */
  proposalId: string;
  /** What this proposal addresses. */
  target: {
    type: "agent" | "provider" | "workflow" | "prompt" | "tool" | "memory" | "output";
    entityId: string;
  };
  /** Type of improvement. */
  type: "parameter_tuning" | "prompt_optimization" | "model_switch" | "parameter_adjustment" | "workflow_restructure" | "tool_replacement";
  /** Current performance. */
  currentPerformance: CurrentPerformance;
  /** Proposed changes. */
  proposedChanges: ProposedChange[];
  /** Expected impact. */
  expectedImpact: ExpectedImpact;
  /** Confidence in proposal (0-1). */
  confidence: number;
  /** Priority level. */
  priority: "low" | "medium" | "high" | "critical";
  /** Status. */
  status: "proposed" | "under_review" | "approved" | "rejected" | "implemented" | "rolled_back";
  /** Who proposed this. */
  proposedBy: "automated" | "human";
  /** Human reviewer (if applicable). */
  reviewer?: string;
  /** Created/updated timestamps. */
  createdAt: string;
  updatedAt: string;
}

export interface CurrentPerformance {
  metricId: string;
  currentValue: number;
  baselineValue: number;
  trend: "improving" | "degrading" | "stable";
}

export interface ProposedChange {
  /** What parameter/setting to change. */
  parameter: string;
  /** Current value. */
  currentValue: Json;
  /** Proposed new value. */
  proposedValue: Json;
  /** Rationale for this change. */
  rationale: string;
  /** Risk level. */
  risk: "low" | "medium" | "high";
  /** Rollback plan. */
  rollbackPlan: string;
}

export interface ExpectedImpact {
  /** Expected change in primary metric. */
  primaryMetricChange: {
    metricId: string;
    expectedDelta: number;
    confidence: number;
  };
  /** Secondary metric impacts. */
  secondaryImpacts: Array<{
    metricId: string;
    expectedDelta: number;
    confidence: number;
  }>;
  /** Risk assessment. */
  riskAssessment: {
    level: "low" | "medium" | "high";
    mitigation: string;
  };
  /** Estimated time to realize improvement. */
  estimatedTimeToImpact: string; // e.g., "1h", "1d", "1w"
}

/** Continuous improvement loop engine. */
export interface ImprovementLoop {
  /** Analyze performance and generate proposals. */
  analyzeAndPropose(config: ImprovementAnalysisConfig): Promise<ImprovementProposal[]>;

  /** Submit proposal for review. */
  submitProposal(proposal: ImprovementProposal): Promise<ImprovementProposal>;

  /** Approve/reject a proposal. */
  reviewProposal(proposalId: string, decision: "approve" | "reject", reviewer: string, notes?: string): Promise<void>;

  /** Execute approved proposal. */
  executeProposal(proposalId: string): Promise<ExecutionResult>;

  /** Monitor impact of executed proposal. */
  monitorImpact(proposalId: string): Promise<ImpactReport>;

  /** Rollback a deployed change. */
  rollback(proposalId: string, reason: string): Promise<void>;
}

export interface ImprovementAnalysisConfig {
  /** Entities to analyze. */
  targets: Array<{ type: string; entityId: string }>;
  /** Minimum confidence for proposals. */
  minConfidence: number;
  /** Maximum proposals per cycle. */
  maxProposals: number;
  /** Minimum expected improvement. */
  minExpectedImprovement: number;
  /** Whether to auto-approve low-risk changes. */
  autoApproveLowRisk: boolean;
}

export interface ExecutionResult {
  success: boolean;
  changesApplied: string[];
  errors: string[];
  rollbackAvailable: boolean;
}

export interface ImpactReport {
  proposalId: string;
  /** Actual vs expected impact. */
  actualVsExpected: Array<{
    metricId: string;
    expectedDelta: number;
    actualDelta: number;
    variance: number;
  }>;
  /** Overall assessment. */
  overallAssessment: "success" | "partial_success" | "no_change" | "negative_impact" | "rolled_back";
  /** Lessons learned. */
  lessonsLearned: string[];
  /** Recommendations for future. */
  recommendations: string[];
  generatedAt: string;
}

/** Automated improvement cycle. */
export interface ImprovementCycle {
  /** Cycle configuration. */
  config: CycleConfig;
  /** Current cycle status. */
  status: "idle" | "analyzing" | "proposing" | "reviewing" | "executing" | "monitoring" | "completed" | "failed";
  /** Current cycle number. */
  cycleNumber: number;
  /** Started at. */
  startedAt: string;
  /** Completed at. */
  completedAt?: string;
  /** Proposals in this cycle. */
  proposals: string[];
  /** Results summary. */
  summary?: CycleSummary;
}

export interface CycleConfig {
  /** How often to run improvement cycles. */
  frequency: "continuous" | "hourly" | "daily" | "weekly";
  /** Time window for analysis. */
  analysisWindow: string; // e.g., "7d", "30d"
  /** Minimum data points required. */
  minDataPoints: number;
  /** Maximum proposals per cycle. */
  maxProposalsPerCycle: number;
  /** Auto-approve threshold. */
  autoApproveThreshold: number;
  /** Require human approval for high-risk. */
  requireHumanApprovalForHighRisk: boolean;
}

export interface CycleSummary {
  proposalsGenerated: number;
  proposalsApproved: number;
  proposalsImplemented: number;
  proposalsRolledBack: number;
  netImpact: number; // overall performance change
  totalCostSavings: number;
  totalLatencyReduction: number;
}